import React from "react";
import { ReportJson, ReportRow } from "../types/report";

interface ReportViewerProps {
  reportJson: ReportJson;
}

const ReportViewer: React.FC<ReportViewerProps> = ({ reportJson }) => {
  const rows: ReportRow[] = Array.isArray(reportJson.data) ? reportJson.data : [];

  if (rows.length === 0) {
    return (
      <div>
        <div>
          Report Generated On: {new Date(reportJson.reportGeneratedOn).toLocaleString()}
        </div>
        <p>No report data available for the selected date range.</p>
      </div>
    );
  }

  return (
    <div>
      <div>
        Report Generated On: {new Date(reportJson.reportGeneratedOn).toLocaleString()}
      </div>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Start</th>
            <th>End</th>
            <th>Venue</th>
            <th>#Attendees</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.id}>
              <td>{r.name}</td>
              <td>{new Date(r.startTimeUtc).toLocaleString()}</td>
              <td>{new Date(r.endTimeUtc).toLocaleString()}</td>
              <td>{r.venue}</td>
              <td>{r.attendeeCount}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ReportViewer;
